changeSet.sql:
UPDATE animal_colors SET specie_id = (SELECT MIN(id) FROM species) WHERE specie_id IS NULL;
INSERT INTO animal_colors (name, created_date, enabled, specie_id) SELECT src.name, src.created_date, src.enabled, s.id FROM (SELECT name, created_date, enabled FROM animal_colors WHERE specie_id = (SELECT MIN(id) FROM species)) src CROSS JOIN species s WHERE s.id <> (SELECT MIN(id) FROM species);
UPDATE animals a JOIN animal_colors old_color ON old_color.id = a.color_id JOIN animal_colors new_color ON new_color.name = old_color.name AND new_color.specie_id = a.specie_id SET a.color_id = new_color.id WHERE old_color.specie_id <> a.specie_id;

INSERT IGNORE INTO animal_colors (name, created_date, enabled, specie_id) SELECT n.name, CURRENT_TIMESTAMP, 1, s.id FROM species s CROSS JOIN ( SELECT 'Negro' AS name UNION ALL SELECT 'Cafe' UNION ALL SELECT 'Blanco' UNION ALL SELECT 'Gris' UNION ALL SELECT 'Crema' UNION ALL SELECT 'Beige' UNION ALL SELECT 'Dorado' UNION ALL SELECT 'Naranja' UNION ALL SELECT 'Rojo' UNION ALL SELECT 'Chocolate' UNION ALL SELECT 'Canela' UNION ALL SELECT 'Azul' UNION ALL SELECT 'Lila' UNION ALL SELECT 'Plateado' UNION ALL SELECT 'Marfil' UNION ALL SELECT 'Arena' UNION ALL SELECT 'Albino' UNION ALL SELECT 'Bicolor' UNION ALL SELECT 'Tricolor' UNION ALL SELECT 'Atigrado' UNION ALL SELECT 'Manchado' UNION ALL SELECT 'Moteado' UNION ALL SELECT 'Aguti' UNION ALL SELECT 'Blanco y Negro' UNION ALL SELECT 'Blanco y Cafe' UNION ALL SELECT 'Blanco y Gris' UNION ALL SELECT 'Blanco y Naranja' UNION ALL SELECT 'Multicolor' UNION ALL SELECT 'Otro' ) n WHERE s.name IN ('Canino', 'Felino');
INSERT IGNORE INTO animal_colors (name, created_date, enabled, specie_id) SELECT n.name, CURRENT_TIMESTAMP, 1, s.id FROM species s CROSS JOIN ( SELECT 'Leonado' AS name UNION ALL SELECT 'Trigueño' UNION ALL SELECT 'Higado' UNION ALL SELECT 'Ruano' UNION ALL SELECT 'Arlequin' UNION ALL SELECT 'Merle' UNION ALL SELECT 'Merle Azul' UNION ALL SELECT 'Merle Rojo' UNION ALL SELECT 'Sable' UNION ALL SELECT 'Negro y Fuego' UNION ALL SELECT 'Manto Negro' ) n WHERE s.name = 'Canino';
INSERT IGNORE INTO animal_colors (name, created_date, enabled, specie_id) SELECT n.name, CURRENT_TIMESTAMP, 1, s.id FROM species s CROSS JOIN ( SELECT 'Carey' AS name UNION ALL SELECT 'Calico' UNION ALL SELECT 'Carey Diluido' UNION ALL SELECT 'Colorpoint' UNION ALL SELECT 'Esmoquin' UNION ALL SELECT 'Humo' UNION ALL SELECT 'Sombreado' UNION ALL SELECT 'Chinchilla' ) n WHERE s.name = 'Felino';
